<?php declare(strict_types=1); namespace Core\Support; final class Str { public static function slug(string $value, string $separator = '-'): string { $value = strtolower(trim($value)); $value = preg_replace('/[^a-z0-9]+/u', $separator, $value) ?? ''; $value = preg_replace('/' . preg_quote($separator, '/') . '{2,}/', $separator, $value) ?? ''; return trim($value, $separator); } public static function snake(string $value): string { $value = preg_replace('/(?<!^)[A-Z]/', '_$0', $value) ?? $value; return strtolower(str_replace(['-', ' '], '_', $value)); } public static function camel(string $value): string { return lcfirst(str_replace(' ', '', ucwords(str_replace(['-', '_'], ' ', $value)))); } public static function studly(string $value): string { return str_replace(' ', '', ucwords(str_replace(['-', '_'], ' ', $value))); } public static function random(int $length = 32): string { return bin2hex(random_bytes((int) ceil($length / 2))); } public static function limit(string $value, int $limit = 100, string $end = '...'): string { if (mb_strlen($value) <= $limit) { return $value; } return rtrim(mb_substr($value, 0, $limit)) . $end; } } 